-- 08 - Boundary and property tests for the chunk arithmetic
--   <CONSUMER_SCHEMA> <CONSUMER_WAREHOUSE>
--
-- WHY THIS FILE EXISTS
--
-- Scale testing and boundary testing find DIFFERENT bugs, and this repo has now
-- been bitten by both:
--
--   * The FLOOR(t/base) carry bug was a DISTRIBUTION bug. It corrupted 1 group in
--     999,934 and was invisible at 2,000 groups. Only volume found it.
--   * The zero-total bug was a DEGENERATE-INPUT bug: LTRIM of an all-zero string
--     returns ''. No group in 200,000 or 10,000,000 rows ever summed to zero, so
--     no amount of volume would have found it. Only a constructed case did.
--
-- So volume is not a substitute for enumerating the boundaries, and guessing
-- cases one at a time is not a method. This file enumerates them.
--
-- WHERE THE BOUNDARIES ACTUALLY ARE
--
-- The chunks are base-10^20, so the interesting values are powers of 10^20 and
-- their neighbours -- NOT powers of two. Powers of two are included anyway
-- because they are what uint256 data actually looks like.
--
-- The harder cases are not single values but CARRY PATTERNS in the SUM:
--   chunk sum = base-1   (no carry)
--   chunk sum = base     (carry, remainder 0)
--   chunk sum = base+1   (carry, remainder 1)
--   chunk sum = k*base   (multi-unit carry)
--   cascading carry, where a carry out of d3 pushes d2 over the base, which
--     pushes d1 over the base, which lands in d0. 10^60-1 has d1=d2=d3=base-1,
--     so two of those rows exercise a triple cascade in one group.
--
-- ORACLE
--
-- Every group is totalled two independent ways: this SQL, and the Python UDAF,
-- which is real arbitrary-precision integer arithmetic. They must agree exactly.
-- Expected totals were also computed in Python offline (scripts/verify_sum.py
-- style) making it a three-way check.

USE WAREHOUSE <CONSUMER_WAREHOUSE>;
USE SCHEMA <CONSUMER_SCHEMA>;

-- Oracle helper: decimal string -> BINARY(32), so the UDAF can total the same rows.
CREATE OR REPLACE FUNCTION U256_ENC(S VARCHAR) RETURNS BINARY
LANGUAGE PYTHON RUNTIME_VERSION='3.11' HANDLER='f'
AS $$
def f(s):
    return None if s is None else int(s).to_bytes(32,'big')
$$;

CREATE OR REPLACE TEMPORARY TABLE BOUNDARY_CASES (grp VARCHAR, value_dec VARCHAR);

CREATE OR REPLACE TEMPORARY TABLE BOUNDARY_CHUNKED AS
SELECT grp, value_dec, U256_ENC(value_dec) AS value_raw,
  TO_DECIMAL(SUBSTR(LPAD(value_dec,80,'0'), 1,20),38,0) AS d0,
  TO_DECIMAL(SUBSTR(LPAD(value_dec,80,'0'),21,20),38,0) AS d1,
  TO_DECIMAL(SUBSTR(LPAD(value_dec,80,'0'),41,20),38,0) AS d2,
  TO_DECIMAL(SUBSTR(LPAD(value_dec,80,'0'),61,20),38,0) AS d3
FROM BOUNDARY_CASES;

-- THE ASSERTION. Expect mismatched = 0. Anything else is a real defect.
WITH t AS (SELECT grp, SUM(d0) t0, SUM(d1) t1, SUM(d2) t2, SUM(d3) t3
           FROM BOUNDARY_CHUNKED GROUP BY grp),
c  AS (SELECT grp,t0,t1,t2, MOD(t3,100000000000000000000) r3,
              (t3-MOD(t3,100000000000000000000))/100000000000000000000 k3 FROM t),
c2 AS (SELECT grp,t0,t1,r3, MOD(t2+k3,100000000000000000000) r2,
              ((t2+k3)-MOD(t2+k3,100000000000000000000))/100000000000000000000 k2 FROM c),
c3 AS (SELECT grp,t0,r3,r2, MOD(t1+k2,100000000000000000000) r1,
              ((t1+k2)-MOD(t1+k2,100000000000000000000))/100000000000000000000 k1 FROM c2),
sqlv AS (SELECT grp, COALESCE(NULLIF(LTRIM(TO_VARCHAR(FLOOR(t0+k1))
   ||LPAD(TO_VARCHAR(FLOOR(r1)),20,'0')||LPAD(TO_VARCHAR(FLOOR(r2)),20,'0')
   ||LPAD(TO_VARCHAR(FLOOR(r3)),20,'0'),'0'),''),'0') AS sql_total FROM c3),
udaf AS (SELECT grp, U256_SUM(value_raw) AS udaf_total FROM BOUNDARY_CHUNKED GROUP BY grp)
SELECT COUNT(*) AS cases,
       COUNT_IF(sql_total =  udaf_total) AS matching,
       COUNT_IF(sql_total <> udaf_total) AS mismatched
FROM sqlv JOIN udaf USING (grp);

-- Per-case detail, for when the assertion above fails.
-- HARNESS NOTE: group names contain uppercase letters (d3_sum_eq_B). When
-- post-processing this output with grep, a [a-z_0-9] character class silently
-- drops those rows and looks like missing data. That cost time once already.
WITH t AS (SELECT grp, SUM(d0) t0, SUM(d1) t1, SUM(d2) t2, SUM(d3) t3
           FROM BOUNDARY_CHUNKED GROUP BY grp),
c  AS (SELECT grp,t0,t1,t2, MOD(t3,100000000000000000000) r3,
              (t3-MOD(t3,100000000000000000000))/100000000000000000000 k3 FROM t),
c2 AS (SELECT grp,t0,t1,r3, MOD(t2+k3,100000000000000000000) r2,
              ((t2+k3)-MOD(t2+k3,100000000000000000000))/100000000000000000000 k2 FROM c),
c3 AS (SELECT grp,t0,r3,r2, MOD(t1+k2,100000000000000000000) r1,
              ((t1+k2)-MOD(t1+k2,100000000000000000000))/100000000000000000000 k1 FROM c2),
sqlv AS (SELECT grp, COALESCE(NULLIF(LTRIM(TO_VARCHAR(FLOOR(t0+k1))
   ||LPAD(TO_VARCHAR(FLOOR(r1)),20,'0')||LPAD(TO_VARCHAR(FLOOR(r2)),20,'0')
   ||LPAD(TO_VARCHAR(FLOOR(r3)),20,'0'),'0'),''),'0') AS sql_total FROM c3),
udaf AS (SELECT grp, U256_SUM(value_raw) AS udaf_total FROM BOUNDARY_CHUNKED GROUP BY grp)
SELECT grp, LENGTH(sql_total) AS digits, sql_total,
       IFF(sql_total = udaf_total,'OK','*** MISMATCH ***') AS verdict
FROM sqlv JOIN udaf USING (grp) ORDER BY grp;

DROP FUNCTION IF EXISTS U256_ENC(VARCHAR);
